'use strict';
/* Мои финансы: local-only PWA. All amounts are integer euro cents. */
const DB_NAME = 'moi-finansy-local-v1', STORE = 'documents', DB_KEY = 'primary';
const $ = s => document.querySelector(s);
const E = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro = x => new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR',minimumFractionDigits:2}).format(x/100);
const signed = x => (x>0?'+':'')+euro(x);
const uid = () => (globalThis.crypto?.randomUUID?.() ?? ('id-'+Date.now()+'-'+Math.random().toString(36).slice(2)));
const today = () => {const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const currentMonth = () => today().slice(0,7);
const parseMoney = v => {const s=String(v??'').trim().replace(/\s/g,'');if(!/^\d+(?:[.,]\d{1,2})?$/.test(s)) throw Error('Укажи корректную сумму с точностью до цента.');const [a,b='']=s.replace(',','.').split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>100000000000)throw Error('Слишком большая сумма.');return n};
const moneyInput = v => (v/100).toFixed(2);
const parseSignedMoney = v => {const s=String(v??'').trim();return s.startsWith('-')?-parseMoney(s.slice(1)):parseMoney(s)};
const formatDate = d => {if(!/^\d{4}-\d{2}-\d{2}$/.test(d??''))return d??'';return new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'})};
const monthTitle = m => new Date(m+'-15T12:00:00').toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
const shiftMonth = (m,delta) => {const [y,mo]=m.split('-').map(Number);const d=new Date(y,mo-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const shiftDue = (date,frequency) => {const [y,m,d]=date.split('-').map(Number);if(frequency==='weekly'){const out=new Date(y,m-1,d+7,12);return [out.getFullYear(),String(out.getMonth()+1).padStart(2,'0'),String(out.getDate()).padStart(2,'0')].join('-')}const mo=frequency==='yearly'?12:1;const target=new Date(y,m-1+mo,1,12);const max=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();return `${target.getFullYear()}-${String(target.getMonth()+1).padStart(2,'0')}-${String(Math.min(d,max)).padStart(2,'0')}`};
const ICON_PATH={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',history:'<path d="M3 12a9 9 0 1 0 3-6.7M3 4v5h5"/><path d="M12 7v5l3 2"/>',budget:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4m8-4v4M3 10h18m-13 4h3m-3 4h7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',minus:'<path d="M5 12h14"/>',swap:'<path d="M4 7h16l-4-4m4 4-4 4M20 17H4l4 4m-4-4 4-4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',edit:'<path d="m4 20 4-.8L20 7a2.1 2.1 0 0 0-3-3L5 16z"/>',chev:'<path d="m9 18 6-6-6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',shield:'<path d="M12 2 4 6v6c0 5 3.5 8.3 8 10 4.5-1.7 8-5 8-10V6z"/><path d="m9 12 2 2 4-4"/>',back:'<path d="m15 18-6-6 6-6"/>',trash:'<path d="M3 6h18m-2 0-1 15H6L5 6m3 0V4h8v2m-6 4v7m4-7v7"/>',pie:'<path d="M21 12A9 9 0 1 1 12 3v9zM12 3a9 9 0 0 1 9 9h-9z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',check:'<path d="m4 12 5 5L20 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4m8-4v4M3 10h18"/>',gear:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4m0-12.8L17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="4"/>',wallet:'<rect x="2" y="5" width="20" height="16" rx="3"/><path d="M2 9h20m-5 6h2"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',file:'<path d="M5 2h9l5 5v15H5zM14 2v5h5m-11 4h8m-8 4h8"/>'};
const ico=(name)=>`<svg class="icon-inline" viewBox="0 0 24 24" aria-hidden="true">${ICON_PATH[name]||ICON_PATH.more}</svg>`;
const acctDefaults=[{id:'must',name:'Обязательные расходы',percent:50,icon:'🏠'},{id:'personal',name:'Личные нужды',percent:20,icon:'✨'},{id:'savings',name:'Сбережения',percent:20,icon:'💎'},{id:'spontaneous',name:'Спонтанные покупки',percent:10,icon:'🎁'}];
const catDefaults=[['food','Продукты','expense','🛒'],['housing','Жильё','expense','🏡'],['transport','Транспорт','expense','🚎'],['health','Здоровье','expense','💊'],['fun','Развлечения','expense','🎮'],['homegoods','Бытовые товары','expense','🧻'],['cafe','Кафе','expense','☕'],['services','Подписки','expense','📱'],['other','Другое','expense','📦'],['salary','Зарплата','income','💼'],['tips','Чаевые','income','💚'],['gift','Подарок','income','🎉'],['other-income','Другой доход','income','💰']].map(([id,name,type,icon])=>({id,name,type,icon,archived:false}));
const freshState=()=>({schema:1,accounts:structuredClone(acctDefaults),categories:structuredClone(catDefaults),transactions:[],budgets:[],subscriptions:[],prefs:{backupReminderDays:7,lastBackupAt:null}});
let state=freshState(),db=null,view='home',detailAccount=null,month=currentMonth(),historySearch='',historyType='all',categoryType='expense',editingTx=null;
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(STORE))req.result.createObjectStore(STORE)};req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result)})}
function dbRead(){return new Promise((resolve,reject)=>{const rq=db.transaction(STORE).objectStore(STORE).get(DB_KEY);rq.onsuccess=()=>resolve(rq.result);rq.onerror=()=>reject(rq.error)})}
function dbWrite(value){return new Promise((resolve,reject)=>{const t=db.transaction(STORE,'readwrite');t.objectStore(STORE).put(value,DB_KEY);t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error)})}
let savePending=Promise.resolve();function commit(){savePending=savePending.catch(()=>{}).then(()=>dbWrite(state));return savePending.catch(err=>{toast('Не удалось сохранить данные: '+err.message);throw err})}
function acc(id){return state.accounts.find(x=>x.id===id)}
function cat(id){return state.categories.find(x=>x.id===id)}
function catName(id){return cat(id)?.name||'Категория удалена'}
function balances(){const b=Object.fromEntries(state.accounts.map(a=>[a.id,0]));for(const t of state.transactions){switch(t.type){case 'income':if(t.allocations){for(const [id,cents] of Object.entries(t.allocations))if(id in b)b[id]+=cents}else if(t.accountId in b)b[t.accountId]+=t.amount;break;case 'expense':case 'courier_payment':if(t.accountId in b)b[t.accountId]-=t.amount;break;case 'transfer':if(t.fromId in b)b[t.fromId]-=t.amount;if(t.toId in b)b[t.toId]+=t.amount;break;case 'adjustment':if(t.accountId in b)b[t.accountId]+=t.delta;break;case 'courier_return':if('must' in b)b.must+=t.amount;break;}}return b}
function allocated(cents){const weights=state.accounts.map(a=>({id:a.id,base:Math.floor(cents*a.percent/100),fraction:(cents*a.percent)%100}));let remain=cents-weights.reduce((s,x)=>s+x.base,0);weights.sort((a,b)=>b.fraction-a.fraction);for(let i=0;i<remain;i++)weights[i%weights.length].base++;return Object.fromEntries(weights.map(x=>[x.id,x.base]))}
function financialStats(m=currentMonth()){const t=state.transactions.filter(t=>t.date.startsWith(m));return {income:t.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),expense:t.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0)}}
function outstanding(){return state.transactions.reduce((sum,t)=>sum+(t.type==='courier_payment'?t.amount:t.type==='courier_return'?-t.amount:0),0)}
function currentBudget(categoryId,m=month){return state.budgets.find(x=>x.categoryId===categoryId&&x.mode==='month'&&x.month===m)||state.budgets.find(x=>x.categoryId===categoryId&&x.mode==='recurring')}
function spent(categoryId,m=month){return state.transactions.filter(x=>x.type==='expense'&&x.categoryId===categoryId&&x.date.startsWith(m)).reduce((s,t)=>s+t.amount,0)}
function txTitle(t){if(t.type==='expense'||t.type==='income')return catName(t.categoryId);if(t.type==='transfer')return 'Перевод между счетами';if(t.type==='adjustment')return 'Корректировка баланса';if(t.type==='courier_payment')return 'Оплата компании';if(t.type==='courier_return')return 'Возврат наличных';return 'Операция'}
function txIcon(t){if(t.type==='expense'||t.type==='income')return cat(t.categoryId)?.icon||'💶';return {transfer:'🔁',adjustment:'⚙️',courier_payment:'🚴',courier_return:'💵'}[t.type]||'💶'}
function txMoney(t){return t.type==='expense'||t.type==='courier_payment'?-t.amount:t.type==='adjustment'?t.delta:t.amount}
function txAccount(t){if(t.type==='transfer')return `${acc(t.fromId)?.name||'—'} → ${acc(t.toId)?.name||'—'}`;if(t.type==='income'&&t.allocations)return 'Автораспределение';if(t.type==='courier_return')return acc('must')?.name||'—';return acc(t.accountId)?.name||'—'}
function txRow(t){const sum=txMoney(t),cls=sum<0?'neg':sum>0?'pos':'';return `<div class="txn-row"><div class="txn-icon">${txIcon(t)}</div><div class="txn-info"><div class="txn-title">${E(txTitle(t))}</div><div class="txn-meta">${E(formatDate(t.date))} · ${E(txAccount(t))}${t.note?' · '+E(t.note):''}</div></div><div class="txn-money mono ${t.type==='transfer'?'':cls}">${t.type==='transfer'?'↔ '+euro(t.amount):signed(sum)}</div><button class="txn-edit" data-action="edit-tx" data-id="${E(t.id)}" aria-label="Подробнее об операции">${ico('chev')}</button></div>`}
const sortTx=(a,b)=>b.date.localeCompare(a.date)||String(b.createdAt).localeCompare(String(a.createdAt));
function nav(){return `<nav class="bottom-nav" aria-label="Разделы">${[['home','home','Главная'],['history','history','История'],['budgets','budget','Бюджеты'],['more','more','Ещё']].map(([v,i,label])=>`<button class="nav-item ${((view===v)||(view==='account'&&v==='home')||(['categories','subscriptions','courier','analytics','settings','backup'].includes(view)&&v==='more'))?'active':''}" data-action="nav" data-id="${v}">${ico(i)}<span>${label}</span></button>`).join('')}</nav>`}
function header(){const titles={home:'Мои финансы',history:'История',budgets:'Бюджеты',more:'Настройки и инструменты',account:acc(detailAccount)?.name||'Счёт',categories:'Категории',subscriptions:'Подписки',courier:'Курьерские расчёты',analytics:'Аналитика',settings:'Настройки счетов',backup:'Резервные копии'};return `<header class="topbar"><div class="logo">${view==='home'?'<div class="logo-mark">◈</div>':`<button class="round-icon" data-action="nav" data-id="${view==='account'?'home':view==='history'||view==='budgets'?'home':'more'}" aria-label="Назад">${ico('back')}</button>`}<div><div class="brand">${E(titles[view]||'Мои финансы')}</div><div class="subtitle">${view==='home'?'Твой личный финансовый центр':'Все данные только на устройстве'}</div></div></div><button class="round-icon" data-action="open-new" aria-label="Добавить операцию">${ico('plus')}</button></header>`}
function homePage(){const b=balances(),total=Object.values(b).reduce((s,x)=>s+x,0),stats=financialStats(),tx=[...state.transactions].sort(sortTx).slice(0,5);const overdue=state.subscriptions.filter(s=>s.active&&s.nextDate<=today()).length;const budgetOver=state.categories.filter(c=>c.type==='expense'&&currentBudget(c.id,currentMonth())&&spent(c.id,currentMonth())>currentBudget(c.id,currentMonth()).amount).length;const reminder=state.prefs.backupReminderDays>0&&state.transactions.length>0&&(!state.prefs.lastBackupAt||Date.now()-new Date(state.prefs.lastBackupAt).getTime()>state.prefs.backupReminderDays*86400000);
return `<section class="hero"><div class="eyebrow">Общий баланс</div><div class="hero-balance mono ${total<0?'neg':''}">${euro(total)}</div><div class="muted small">Сумма четырёх виртуальных счетов</div><div class="hero-bottom"><div class="hero-stat"><div class="eyebrow">${ico('arrow')} Доходы · месяц</div><div class="pos mono">${euro(stats.income)}</div></div><div class="hero-stat"><div class="eyebrow">${ico('minus')} Расходы · месяц</div><div class="mono">${euro(stats.expense)}</div></div></div></section>
<section><div class="section-head"><h2>Мои счета</h2><button class="text-btn" data-action="nav" data-id="settings">Настроить →</button></div><div class="accounts-grid">${state.accounts.map(a=>`<button class="account-card" data-action="account" data-id="${E(a.id)}"><div class="account-top"><span class="account-icon">${E(a.icon)}</span><span class="account-pct">${a.percent}%</span></div><div><div class="account-name">${E(a.name)}</div><div class="account-money mono ${b[a.id]<0?'neg':''}">${euro(b[a.id])}</div></div></button>`).join('')}</div></section>
<section><div class="section-head"><h2>Быстрые действия</h2></div><div class="quick-actions"><button class="quick-btn primary" data-action="open-expense">${ico('minus')}<span>Расход</span></button><button class="quick-btn" data-action="open-income">${ico('plus')}<span>Доход</span></button><button class="quick-btn" data-action="open-transfer">${ico('swap')}<span>Перевод</span></button></div></section>
${reminder?`<button class="alert" style="width:100%;text-align:left" data-action="nav" data-id="backup">${ico('shield')}<span>Пора сохранить резервную копию. Твои данные находятся только на этом устройстве. <b>Создать →</b></span></button>`:''}
${overdue?`<button class="alert" style="width:100%;text-align:left" data-action="nav" data-id="subscriptions">${ico('bell')}<span>Есть подписки к оплате: ${overdue}. Открой список и отметь оплаченные.</span></button>`:''}
${budgetOver?`<button class="alert" style="width:100%;text-align:left" data-action="nav" data-id="budgets">${ico('budget')}<span>Превышен лимит в ${budgetOver} ${budgetOver===1?'категории':'категориях'} текущего месяца.</span></button>`:''}
<section><div class="section-head"><h2>Последние операции</h2><button class="text-btn" data-action="nav" data-id="history">Вся история →</button></div><div class="panel">${tx.length?`<div class="transaction-list">${tx.map(txRow).join('')}</div>`:`<div class="empty"><div class="empty-icon">🌱</div>Пока нет операций.<br>Добавь первый доход или расход.</div>`}</div></section><div class="footer-note">Без облака и аккаунтов · Всё сохраняется на телефоне</div>`}
function accountPage(){const a=acc(detailAccount);if(!a){view='home';return homePage()}const b=balances(),tx=[...state.transactions].filter(t=>t.accountId===a.id||t.fromId===a.id||t.toId===a.id||(t.type==='income'&&t.allocations&&a.id in t.allocations)||(t.type==='courier_return'&&a.id==='must')).sort(sortTx);return `<div class="account-detail-top"><div class="account-icon" style="margin:auto">${E(a.icon)}</div><div class="muted small" style="margin-top:13px">${E(a.name)}</div><div class="big mono ${b[a.id]<0?'neg':''}">${euro(b[a.id])}</div><span class="category-pill">${a.percent}% от авто-дохода</span></div><div class="grid2"><button class="btn outline" data-action="open-transfer" data-id="${E(a.id)}">${ico('swap')} Перевести</button><button class="btn outline" data-action="open-adjustment" data-id="${E(a.id)}">${ico('edit')} Изменить баланс</button></div><section><div class="section-head"><h2>Движение по счёту</h2></div><div class="panel">${tx.length?tx.map(txRow).join(''):'<div class="empty">Операций пока нет</div>'}</div></section>`}
function historyPage(){let tx=[...state.transactions].sort(sortTx).filter(t=>historyType==='all'||t.type===historyType).filter(t=>!historySearch||[txTitle(t),txAccount(t),t.note||'',t.date].join(' ').toLowerCase().includes(historySearch.toLowerCase()));return `<div class="field"><label for="history-search">Поиск по операциям</label><input id="history-search" placeholder="Категория, счёт, примечание…" value="${E(historySearch)}" /></div><div class="chip-row">${[['all','Все'],['expense','Расходы'],['income','Доходы'],['transfer','Переводы'],['courier_payment','Курьерство'],['adjustment','Корректировки']].map(([id,text])=>`<button class="chip ${historyType===id?'active':''}" data-action="history-type" data-id="${id}">${text}</button>`).join('')}</div><div class="panel"><div class="section-head"><div class="panel-title">Найдено: ${tx.length}</div><button class="text-btn" data-action="csv">Экспорт CSV</button></div>${tx.length?tx.map(txRow).join(''):'<div class="empty">Подходящих операций нет</div>'}</div>`}
function budgetPage(){const bs=state.categories.filter(c=>c.type==='expense'&&!c.archived||state.budgets.some(b=>b.categoryId===c.id)).map(c=>({c,b:currentBudget(c.id)})).filter(x=>x.b);let sumLimit=0,sumSpent=0;const items=bs.map(({c,b})=>{const s=spent(c.id);sumLimit+=b.amount;sumSpent+=s;const pct=b.amount>0?Math.min(s/b.amount*100,100):100;return `<div class="budget-item"><div class="budget-top"><div><div class="budget-name">${E(c.icon)} ${E(c.name)}</div><div class="muted tiny" style="margin-top:5px">${b.mode==='month'?'Лимит на этот месяц':'Повторяется каждый месяц'}</div></div><button class="text-btn" data-action="edit-budget" data-id="${E(b.id)}">${euro(s)} / ${euro(b.amount)} ${ico('edit')}</button></div><div class="progress-track"><div class="progress-fill ${s>b.amount?'over':''}" style="width:${pct}%"></div></div>${s>b.amount?`<div class="small neg" style="margin-top:7px">Превышение: ${euro(s-b.amount)}</div>`:''}</div>`}).join('');return `<div class="month-switch"><button data-action="month-prev" aria-label="Предыдущий месяц">‹</button><strong>${E(monthTitle(month))}</strong><button data-action="month-next" aria-label="Следующий месяц">›</button></div><section class="panel"><div class="eyebrow">Лимиты категорий</div><div style="font-size:27px;font-weight:800;margin-top:9px" class="mono">${euro(sumSpent)} <span class="muted" style="font-size:13px;font-weight:500">из ${euro(sumLimit)}</span></div><div class="muted small" style="margin-top:7px">Контроль расходов, без запрета превышений</div></section><section><div class="section-head"><h2>Бюджеты категорий</h2><button class="text-btn" data-action="new-budget">+ Добавить</button></div><div class="panel">${items||'<div class="empty">Нет бюджетов на этот месяц. Создай лимит для нужной категории.</div>'}</div></section><div class="alert info">${ico('budget')}<span>Бюджеты привязаны к категориям расходов, а не к счетам. Разовый лимит месяца заменяет ежемесячный для этой категории.</span></div>`}
function morePage(){const opts=[['analytics','pie','Аналитика','Доходы и расходы по месяцам'],['courier','wallet','Курьерские расчёты','Оплата компании, возврат, чаевые'],['subscriptions','bell','Подписки','Напоминания и отметки оплаты'],['categories','filter','Мои категории','Добавить, переименовать, архивировать'],['settings','gear','Счета и проценты','Названия и авто-распределение'],['backup','shield','Копии и экспорт','JSON, восстановление, CSV']];return `<div class="stack">${opts.map(([id,i,name,desc])=>`<button class="list-button" data-action="nav" data-id="${id}"><div class="symbol">${ico(i)}</div><div class="grow"><b>${name}</b><div class="desc">${desc}</div></div><span class="arrow">${ico('chev')}</span></button>`).join('')}</div><div class="footer-note">Мои финансы · Локальная версия 1.0<br>Не связывается с банковскими аккаунтами и не отправляет данные на сервер.</div>`}
function categoriesPage(){const cats=state.categories.filter(c=>c.type===categoryType);return `<div class="chip-row"><button class="chip ${categoryType==='expense'?'active':''}" data-action="category-type" data-id="expense">Расходы</button><button class="chip ${categoryType==='income'?'active':''}" data-action="category-type" data-id="income">Доходы</button></div><button class="btn full" data-action="new-category">${ico('plus')} Новая категория</button><div class="panel">${cats.map(c=>`<div class="setting-row"><div style="font-size:22px">${E(c.icon)}</div><div class="details"><b style="${c.archived?'opacity:.55':''}">${E(c.name)}</b><p>${c.archived?'В архиве':'Активна'}</p></div><button class="btn small outline" data-action="edit-category" data-id="${E(c.id)}">Изменить</button></div>`).join('')}</div><div class="alert info">${ico('shield')}<span>Использованные категории архивируются, а не удаляются: история и статистика сохраняются.</span></div>`}
function settingsPage(){return `<div class="panel"><div class="panel-title">Счета и проценты распределения</div><div class="muted small" style="margin:8px 0 14px">Проценты должны в сумме составлять 100%. Существующие операции не изменяются.</div><form class="sheet-form" data-form="accounts">${state.accounts.map(a=>`<div class="setting-row"><span style="font-size:21px">${E(a.icon)}</span><div class="details"><label class="tiny muted">Название счёта</label><input name="name-${a.id}" aria-label="Название: ${E(a.name)}" value="${E(a.name)}" required maxlength="36" /></div><div><label class="tiny muted">%</label><input name="percent-${a.id}" type="number" min="0" max="100" step="1" value="${a.percent}" required aria-label="Процент: ${E(a.name)}" /></div></div>`).join('')}<button class="btn full" type="submit">Сохранить изменения</button></form></div><div class="alert info">${ico('shield')}<span>Все счета виртуальные. Они нужны для планирования и не отражают автоматически баланс банковской карты.</span></div>`}
function subscriptionsPage(){const subs=[...state.subscriptions].sort((a,b)=>a.nextDate.localeCompare(b.nextDate));return `<button class="btn full" data-action="new-subscription">${ico('plus')} Новая подписка</button><div class="panel">${subs.length?subs.map(s=>`<div class="setting-row"><div class="details"><b>${E(s.name)}</b><p>${euro(s.amount)} · ${E({monthly:'ежемесячно',weekly:'еженедельно',yearly:'ежегодно'}[s.frequency])} · ${E(formatDate(s.nextDate))}</p><p class="${s.active&&s.nextDate<=today()?'amber':''}">${!s.active?'Приостановлена':s.nextDate<=today()?'Пора оплатить':'Ожидается'}</p></div><div class="stack" style="gap:6px">${s.active?`<button class="btn small" data-action="pay-subscription" data-id="${E(s.id)}">Оплачено</button>`:''}<button class="btn small outline" data-action="edit-subscription" data-id="${E(s.id)}">Изменить</button></div></div>`).join(''):'<div class="empty">Здесь появятся твои регулярные платежи.</div>'}</div><div class="alert info">${ico('bell')}<span>Напоминания отображаются внутри приложения при открытии. Автоматического списания нет; системные push-уведомления в этой локальной версии не используются.</span></div>`}
function courierPage(){const debt=outstanding(),t=state.transactions.filter(x=>x.type.startsWith('courier_')).sort(sortTx);return `<section class="hero"><div class="eyebrow">Компания должна вернуть</div><div class="hero-balance mono">${euro(debt)}</div><div class="muted small">Сумма временно оплачена из «Обязательных расходов»</div></section><div class="grid2"><button class="btn outline" data-action="courier-pay">${ico('minus')} Оплата компании</button><button class="btn" data-action="courier-return">${ico('plus')} Внести наличные</button></div><div class="alert info">${ico('shield')}<span>Возврат возвращает деньги на «Обязательные расходы». Подтверждённые чаевые учитываются как отдельный доход. Личные внесённые наличные не считаются зарплатой.</span></div><section><div class="section-head"><h2>Курьерские операции</h2></div><div class="panel">${t.length?t.map(txRow).join(''):'<div class="empty">Нет курьерских операций.</div>'}</div></section>`}
function analyticsPage(){const months=Array.from({length:6},(_,i)=>shiftMonth(currentMonth(),i-5)),points=months.map(m=>({...financialStats(m),m})),max=Math.max(1,...points.map(x=>x.expense));const s=financialStats(month);const top=state.categories.filter(c=>c.type==='expense').map(c=>({name:c.name,icon:c.icon,amount:spent(c.id,month)})).filter(x=>x.amount>0).sort((a,b)=>b.amount-a.amount);return `<div class="month-switch"><button data-action="month-prev">‹</button><strong>${E(monthTitle(month))}</strong><button data-action="month-next">›</button></div><div class="grid2"><div class="panel"><div class="eyebrow">Доходы</div><div class="pos mono" style="font-size:21px;font-weight:770;margin-top:8px">${euro(s.income)}</div></div><div class="panel"><div class="eyebrow">Расходы</div><div class="mono" style="font-size:21px;font-weight:770;margin-top:8px">${euro(s.expense)}</div></div></div><div class="panel"><div class="panel-title">Расходы за последние 6 месяцев</div><div class="chart-bars">${points.map(p=>`<div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(3,(p.expense/max)*97)}px" title="${E(p.m)}: ${euro(p.expense)}"></div><div class="chart-label">${E(p.m.slice(5))}</div></div>`).join('')}</div></div><div class="panel"><div class="panel-title">На что ушли деньги</div>${top.length?top.map(x=>`<div class="setting-row"><span>${E(x.icon)}</span><b class="grow">${E(x.name)}</b><span class="mono">${euro(x.amount)}</span></div>`).join(''):'<div class="empty">Расходов за этот месяц пока нет</div>'}</div>`}
function backupPage(){const last=state.prefs.lastBackupAt?new Date(state.prefs.lastBackupAt).toLocaleString('ru-RU'):'Ещё не создана';return `<div class="panel stack"><div style="font-size:28px">🛡️</div><h2>Твои данные — под твоим контролем</h2><p class="muted small" style="line-height:1.6">Создавай JSON-файл с полным состоянием приложения и сохраняй его за пределами телефона, например в Google Drive.</p><div class="setting-row"><div><b>Последняя копия</b><p class="muted small">${E(last)}</p></div></div><button class="btn full" data-action="backup-export">${ico('download')} Создать резервную копию</button><button class="btn full outline" data-action="backup-import">${ico('upload')} Восстановить из JSON</button><button class="btn full ghost" data-action="csv">${ico('file')} Экспортировать операции CSV</button></div><div class="panel"><div class="panel-title">Напоминание о копии</div><div class="muted small" style="margin:9px 0">Напоминание появится на главной при следующем открытии приложения.</div><div class="field"><label>Период</label><select id="backup-days"><option value="7" ${state.prefs.backupReminderDays===7?'selected':''}>Каждые 7 дней</option><option value="30" ${state.prefs.backupReminderDays===30?'selected':''}>Каждые 30 дней</option><option value="0" ${state.prefs.backupReminderDays===0?'selected':''}>Не напоминать</option></select></div></div><div class="alert">${ico('shield')}<span>Удаление данных браузера, переустановка приложения или потеря телефона могут уничтожить локальную базу. JSON-файл нужно хранить отдельно.</span></div><input id="restore-file" type="file" accept="application/json,.json" hidden />`}
function render(){const viewHTML={home:homePage,account:accountPage,history:historyPage,budgets:budgetPage,more:morePage,categories:categoriesPage,settings:settingsPage,subscriptions:subscriptionsPage,courier:courierPage,analytics:analyticsPage,backup:backupPage}[view]||homePage;$('#app').innerHTML=`<div class="app-shell">${header()}<main class="main">${viewHTML()}</main>${nav()}</div>`}
function toast(message){const root=$('#toast-root');root.innerHTML=`<div class="toast">${E(message)}</div>`;clearTimeout(toast._timer);toast._timer=setTimeout(()=>{root.innerHTML=''},3500)}
function modal(title,inner,formType){$('#modal-root').innerHTML=`<div class="sheet-backdrop" id="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="sheet-handle"></div><div class="sheet-head"><h2>${E(title)}</h2><button class="close-btn" data-action="close-modal" aria-label="Закрыть">×</button></div><form class="sheet-form" data-form="${E(formType)}">${inner}</form></section></div>`;const focus=$('#modal-root input, #modal-root select');if(focus)focus.focus({preventScroll:true})}
function closeModal(){$('#modal-root').innerHTML='';editingTx=null}
const field=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${E(label)}</label><input id="f-${name}" name="${E(name)}" type="${type}" value="${E(value)}" ${extra}></div>`;
const selector=(name,label,items,selected,empty=false)=>`<div class="field"><label for="f-${name}">${E(label)}</label><select id="f-${name}" name="${E(name)}" required>${empty?'<option value="">Выбрать…</option>':''}${items.map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.name)}</option>`).join('')}</select></div>`;
const catsFor=(type,selected)=>state.categories.filter(c=>c.type===type&&(!c.archived||c.id===selected)).map(c=>({id:c.id,name:`${c.icon} ${c.name}`}));
function noteField(note=''){return field('note','Комментарий (необязательно)',note,'text','maxlength="150"')}
function dateField(date){return field('date','Дата операции',date||today(),'date','required')}
function submitBtn(text='Сохранить операцию'){return `<button class="btn full" type="submit">${E(text)}</button>`}
function newExpense(t=null){editingTx=t?.id||null;modal(t?'Редактировать расход':'Новый расход',`${field('amount','Сумма (€)',t?moneyInput(t.amount):'','text','required inputmode="decimal" placeholder="0,00"')}${selector('category','Категория расходов',catsFor('expense',t?.categoryId),t?.categoryId||'food')}${selector('account','С какого счёта списать?',state.accounts,t?.accountId||'',true)}${dateField(t?.date)}${noteField(t?.note)}${submitBtn(t?'Сохранить изменения':'Добавить расход')}`, 'expense')}
function newIncome(t=null){editingTx=t?.id||null;const auto=t?t.allocations!==undefined:true;modal(t?'Редактировать доход':'Новый доход',`${field('amount','Сумма (€)',t?moneyInput(t.amount):'','text','required inputmode="decimal" placeholder="0,00"')}${selector('category','Категория доходов',catsFor('income',t?.categoryId),t?.categoryId||'salary')}<div class="field"><label>Распределение</label><select name="method" id="income-method"><option value="auto" ${auto?'selected':''}>Автоматически по процентам</option><option value="manual" ${!auto?'selected':''}>Вручную на один счёт</option></select><div class="field-hint">Авто: ${state.accounts.map(a=>`${a.percent}% — ${E(a.name)}`).join(' · ')}</div></div>${selector('account','Счёт для ручного зачисления',state.accounts,t?.accountId||'must')}${dateField(t?.date)}${noteField(t?.note)}${submitBtn(t?'Сохранить изменения':'Добавить доход')}`, 'income')}
function newTransfer(t=null,fromId=null){editingTx=t?.id||null;modal(t?'Редактировать перевод':'Перевод между счетами',`${field('amount','Сумма (€)',t?moneyInput(t.amount):'','text','required inputmode="decimal"')}${selector('from','Со счёта',state.accounts,t?.fromId||fromId||'must')}${selector('to','На счёт',state.accounts,t?.toId||'personal')}${dateField(t?.date)}${noteField(t?.note)}${submitBtn(t?'Сохранить изменения':'Перевести')}`, 'transfer')}
function adjustment(accountId){const a=acc(accountId),b=balances();modal('Корректировка счёта',`<div class="alert info">Текущий баланс «${E(a.name)}»: ${euro(b[a.id])}. Корректировка сохраняется отдельно, не как доход или расход.</div><div class="field"><label>Способ</label><select name="mode"><option value="set">Установить точный баланс</option><option value="plus">Добавить сумму</option><option value="minus">Вычесть сумму</option></select></div>${field('amount','Сумма (€)',moneyInput(b[a.id]),'text','inputmode="decimal" required')}${field('reason','Причина (необязательно)','','text','maxlength="150"')}<input type="hidden" name="account" value="${E(accountId)}" />${dateField(today())}${submitBtn('Применить корректировку')}`, 'adjustment')}
function newBudget(b=null){const categoryId=b?.categoryId||state.categories.find(c=>c.type==='expense'&&!c.archived)?.id;const ids=state.categories.filter(c=>c.type==='expense'&&(!c.archived||c.id===categoryId)).map(c=>({id:c.id,name:`${c.icon} ${c.name}`}));modal(b?'Изменить бюджет':'Создать бюджет',`${selector('category','Категория расходов',ids,categoryId)}${field('amount','Лимит (€)',b?moneyInput(b.amount):'','text','required inputmode="decimal"')}<div class="field"><label>Период действия</label><select name="mode"><option value="recurring" ${b?.mode==='recurring'?'selected':''}>Каждый месяц</option><option value="month" ${b?.mode==='month'?'selected':''}>Только выбранный месяц</option></select></div>${field('month','Месяц для разового лимита',b?.month||month,'month','required')}<input type="hidden" name="id" value="${E(b?.id||'')}" />${submitBtn('Сохранить бюджет')}${b?`<button class="btn danger full" type="button" data-action="delete-budget" data-id="${E(b.id)}">Удалить этот лимит</button>`:''}`, 'budget')}
function newCategory(c=null){modal(c?'Редактировать категорию':'Новая категория',`${field('name','Название',c?.name||'','text','required maxlength="45"')}${field('icon','Иконка (например, 🍕)',c?.icon||'🏷️','text','maxlength="6" required')}<input type="hidden" name="type" value="${E(c?.type||categoryType)}"/><input type="hidden" name="id" value="${E(c?.id||'')}"/>${c?`<div class="field"><label>Статус</label><select name="archived"><option value="false" ${!c.archived?'selected':''}>Активна</option><option value="true" ${c.archived?'selected':''}>В архиве</option></select></div>`:''}${submitBtn(c?'Сохранить':'Добавить категорию')}${c?`<button class="btn danger full" type="button" data-action="delete-category" data-id="${E(c.id)}">Удалить категорию (если не использовалась)</button>`:''}`, 'category')}
function newSubscription(s=null){modal(s?'Настроить подписку':'Новая подписка',`${field('name','Название',s?.name||'','text','required maxlength="60"')}${field('amount','Стоимость (€)',s?moneyInput(s.amount):'','text','inputmode="decimal" required')}${selector('category','Категория расхода',catsFor('expense',s?.categoryId),s?.categoryId||'services')}${selector('account','Счёт для оплаты',state.accounts,s?.accountId||'must')}<div class="field"><label>Периодичность</label><select name="frequency"><option value="monthly" ${s?.frequency==='monthly'?'selected':''}>Каждый месяц</option><option value="weekly" ${s?.frequency==='weekly'?'selected':''}>Каждую неделю</option><option value="yearly" ${s?.frequency==='yearly'?'selected':''}>Каждый год</option></select></div>${field('nextDate','Следующая дата оплаты',s?.nextDate||today(),'date','required')}<div class="field"><label>Статус</label><select name="active"><option value="true" ${s?.active!==false?'selected':''}>Активна</option><option value="false" ${s?.active===false?'selected':''}>На паузе</option></select></div><input type="hidden" name="id" value="${E(s?.id||'')}"/>${submitBtn(s?'Сохранить':'Добавить подписку')}${s?`<button type="button" class="btn danger full" data-action="delete-subscription" data-id="${E(s.id)}">Удалить подписку</button>`:''}`, 'subscription')}
function courierPayment(){modal('Оплата курьерской компании',`<div class="alert info">Списание с «Обязательных расходов» создаст сумму к возврату, а не обычный расход категории.</div>${field('amount','Уплачено компании (€)','','text','required inputmode="decimal"')}${dateField(today())}${noteField('')}${submitBtn('Учесть оплату')}`, 'courier_payment')}
function courierReturn(){const o=outstanding();modal('Внесение наличных',`<div class="alert info">Компания должна: ${euro(o)}. На счёт «Обязательные расходы» вернётся не больше этого долга. Остаток можно подтвердить как чаевые; собственные наличные доходом не считаются.</div>${field('deposit','Внесено наличных (€)','','text','required inputmode="decimal"')}${field('tips','Из остатка это чаевые (€)','0,00','text','required inputmode="decimal"')}<div class="field-hint">Пример: долг 9,50 €, внесено 10 €, чаевые 0,50 €. Можно вернуть долг частично.</div>${dateField(today())}${noteField('')}${submitBtn('Учесть внесение')}`, 'courier_return')}
function editTransaction(t){const details=`<div class="panel"><div class="eyebrow">${E(txTitle(t))}</div><div style="font-size:28px;font-weight:750;margin-top:10px" class="${txMoney(t)<0?'neg':'pos'} mono">${signed(txMoney(t))}</div><p class="muted small" style="margin-top:9px">${E(formatDate(t.date))} · ${E(txAccount(t))}</p>${t.note?`<p style="margin-top:10px">${E(t.note)}</p>`:''}${t.type==='courier_return'?`<p class="muted small" style="margin-top:10px">Наличные: ${euro(t.deposited)} · чаевые: ${euro(t.tipAmount||0)}</p>`:''}</div><button type="button" class="btn full outline" data-action="edit-tx-full" data-id="${E(t.id)}">${ico('edit')} Изменить операцию</button><button type="button" class="btn full danger" data-action="delete-tx" data-id="${E(t.id)}">${ico('trash')} Удалить операцию</button>`;modal('Детали операции',details,'transaction-detail')}
function editCourierSimple(t){editingTx=t.id;modal('Редактировать дату и заметку',`<div class="alert info">Для этой курьерской операции можно изменить дату и комментарий. Для изменения суммы удали ошибочную операцию и добавь новую.</div>${dateField(t.date)}${noteField(t.note)}${submitBtn('Сохранить')}`, 'courier-edit')}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
const validDate = s => /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(new Date(s+'T12:00:00').valueOf())&&new Date(s+'T12:00:00').toISOString().slice(0,10)===s;
function requireDate(x){if(!validDate(x))throw Error('Укажи действительную дату.');return x}
function replaceOrPush(t){const idx=state.transactions.findIndex(x=>x.id===editingTx);if(idx>=0){t.id=editingTx;t.createdAt=state.transactions[idx].createdAt;state.transactions[idx]=t}else state.transactions.push(t)}
async function handleForm(form){const v=formData(form),kind=form.dataset.form;try{if(kind==='expense'||kind==='income'){const amount=parseMoney(v.amount);if(amount<=0)throw Error('Сумма должна быть больше нуля.');if(!cat(v.category)||cat(v.category).type!==kind)throw Error('Неверная категория.');const t={id:uid(),type:kind,amount,date:requireDate(v.date),categoryId:v.category,note:v.note.trim().slice(0,150),createdAt:new Date().toISOString()};if(kind==='expense'){if(!acc(v.account))throw Error('Выбери счёт.');t.accountId=v.account}else if(v.method==='auto'){if(state.accounts.reduce((s,a)=>s+a.percent,0)!==100)throw Error('Настрой распределение на 100%.');t.allocations=(editingTx&&state.transactions.find(x=>x.id===editingTx)?.allocations&&state.transactions.find(x=>x.id===editingTx).amount===amount)?structuredClone(state.transactions.find(x=>x.id===editingTx).allocations):allocated(amount)}else{if(!acc(v.account))throw Error('Выбери счёт.');t.accountId=v.account}replaceOrPush(t)}
else if(kind==='transfer'){const amount=parseMoney(v.amount);if(amount<=0||!acc(v.from)||!acc(v.to)||v.from===v.to)throw Error('Укажи разные счета и сумму больше нуля.');replaceOrPush({id:uid(),type:'transfer',amount,fromId:v.from,toId:v.to,date:requireDate(v.date),note:v.note.trim().slice(0,150),createdAt:new Date().toISOString()})}
else if(kind==='adjustment'){const value=v.mode==='set'?parseSignedMoney(v.amount):parseMoney(v.amount),cur=balances()[v.account];if(!acc(v.account))throw Error('Счёт не найден.');const delta=v.mode==='set'?value-cur:v.mode==='minus'?-value:value;if(!delta)throw Error('Баланс не меняется.');state.transactions.push({id:uid(),type:'adjustment',delta,accountId:v.account,date:requireDate(v.date),note:v.reason.trim().slice(0,150),createdAt:new Date().toISOString()})}
else if(kind==='budget'){const amount=parseMoney(v.amount);if(amount<=0)throw Error('Лимит должен быть больше нуля.');if(!cat(v.category)||cat(v.category).type!=='expense')throw Error('Неверная категория.');if(!['recurring','month'].includes(v.mode)||!/^[0-9]{4}-[0-9]{2}$/.test(v.month))throw Error('Некорректный период.');const normalizedMonth=v.mode==='month'?v.month:null;const duplicate=state.budgets.find(x=>x.id!==v.id&&x.categoryId===v.category&&x.mode===v.mode&&(v.mode==='recurring'||x.month===normalizedMonth));if(duplicate)throw Error('Такой бюджет уже существует. Открой его, чтобы изменить.');const b={id:v.id||uid(),categoryId:v.category,amount,mode:v.mode,month:normalizedMonth};const idx=state.budgets.findIndex(x=>x.id===v.id);idx>=0?state.budgets[idx]=b:state.budgets.push(b)}
else if(kind==='category'){const name=v.name.trim().slice(0,45),icon=v.icon.trim().slice(0,6);if(!name||!icon)throw Error('Название и иконка обязательны.');const type=v.type;if(!['income','expense'].includes(type))throw Error('Неверный тип.');if(state.categories.some(x=>x.id!==v.id&&x.type===type&&x.name.toLowerCase()===name.toLowerCase()))throw Error('Категория с таким названием уже существует.');const c={id:v.id||uid(),name,icon,type,archived:v.archived==='true'};const idx=state.categories.findIndex(x=>x.id===v.id);idx>=0?state.categories[idx]=c:state.categories.push(c)}
else if(kind==='subscription'){const amount=parseMoney(v.amount);if(amount<=0||!v.name.trim())throw Error('Укажи название и сумму.');if(!acc(v.account)||!cat(v.category)||cat(v.category).type!=='expense'||!['monthly','weekly','yearly'].includes(v.frequency))throw Error('Проверь счёт, категорию и период.');const s={id:v.id||uid(),name:v.name.trim().slice(0,60),amount,categoryId:v.category,accountId:v.account,frequency:v.frequency,nextDate:requireDate(v.nextDate),active:v.active==='true'};const idx=state.subscriptions.findIndex(x=>x.id===v.id);idx>=0?state.subscriptions[idx]=s:state.subscriptions.push(s)}
else if(kind==='accounts'){const updated=state.accounts.map(a=>({ ...a,name:String(v[`name-${a.id}`]).trim().slice(0,36),percent:Number(v[`percent-${a.id}`])}));if(updated.some(a=>!a.name||!Number.isInteger(a.percent)||a.percent<0||a.percent>100))throw Error('Названия обязательны, проценты — целые от 0 до 100.');if(updated.reduce((s,a)=>s+a.percent,0)!==100)throw Error('Сумма процентов должна быть ровно 100%.');state.accounts=updated}
else if(kind==='courier_payment'){const amount=parseMoney(v.amount);if(amount<=0)throw Error('Сумма должна быть больше нуля.');state.transactions.push({id:uid(),type:kind,amount,accountId:'must',date:requireDate(v.date),note:v.note.trim().slice(0,150),createdAt:new Date().toISOString()})}
else if(kind==='courier_return'){const deposit=parseMoney(v.deposit),tips=parseMoney(v.tips);if(deposit<=0)throw Error('Сумма внесения должна быть больше нуля.');const reimbursement=Math.min(outstanding(),deposit);if(tips>deposit-reimbursement)throw Error(`Чаевые не могут превышать остаток после возврата: ${euro(deposit-reimbursement)}.`);requireDate(v.date);const base={date:v.date,note:v.note.trim().slice(0,150),createdAt:new Date().toISOString()};if(reimbursement>0)state.transactions.push({...base,id:uid(),type:'courier_return',amount:reimbursement,deposited:deposit,tipAmount:tips});if(tips>0)state.transactions.push({...base,id:uid(),type:'income',amount:tips,categoryId:'tips',allocations:allocated(tips),note:'Чаевые · '+base.note});if(!reimbursement&&!tips)throw Error('Нет долга и чаевых к зачислению. Собственные наличные не нужно записывать как доход.');if(deposit-reimbursement-tips>0)toast(`${euro(deposit-reimbursement-tips)} собственных наличных не добавлено в доход.`)}
else if(kind==='courier-edit'){const t=state.transactions.find(x=>x.id===editingTx);if(!t)throw Error('Операция не найдена.');t.date=requireDate(v.date);t.note=v.note.trim().slice(0,150)}
else return;
await commit();closeModal();render();if(kind!=='courier_return')toast('Сохранено ✓');else toast('Внесение учтено ✓')
}catch(e){toast(e.message||'Ошибка сохранения');console.error(e)}}
function exportFile(name,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function exportBackup(){const content=JSON.stringify({format:'moi-finansy-backup',schema:1,createdAt:new Date().toISOString(),data:state},null,2);exportFile('Moi_Finansy_Backup_'+today()+'.json',content,'application/json;charset=utf-8');state.prefs.lastBackupAt=new Date().toISOString();await commit();render();toast('Файл резервной копии подготовлен. Сохрани его вне телефона.')}
function exportCSV(){const headers=['Дата','Тип','Категория','Счет / маршрут','Сумма EUR','Комментарий','ID'];const typeNames={income:'Доход',expense:'Расход',transfer:'Перевод',adjustment:'Корректировка',courier_payment:'Оплата компании',courier_return:'Возврат курьерских денег'};const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const rows=[headers,...[...state.transactions].sort(sortTx).map(t=>[t.date,typeNames[t.type]||t.type,t.categoryId?catName(t.categoryId):'',txAccount(t),(txMoney(t)/100).toFixed(2).replace('.',','),t.note||'',t.id])];exportFile('Moi_Finansy_Operations_'+today()+'.csv','\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV-файл подготовлен')}
function validateBackup(raw){if(!raw||raw.format!=='moi-finansy-backup'||raw.schema!==1||!raw.data)throw Error('Неверный формат резервной копии.');const d=raw.data;if(d.schema!==1||!Array.isArray(d.accounts)||d.accounts.length!==4||!Array.isArray(d.categories)||!Array.isArray(d.transactions)||!Array.isArray(d.budgets)||!Array.isArray(d.subscriptions)||!d.prefs)throw Error('В файле отсутствуют необходимые данные.');const ids=d.accounts.map(a=>a.id);if(!['must','personal','savings','spontaneous'].every(id=>ids.includes(id)))throw Error('Неизвестная структура счетов.');if(d.accounts.some(a=>!Number.isInteger(a.percent)||a.percent<0||a.percent>100||typeof a.name!=='string')||d.accounts.reduce((s,a)=>s+a.percent,0)!==100)throw Error('Некорректные настройки счетов.');const validCents=v=>Number.isSafeInteger(v)&&Math.abs(v)<1000000000000;
if(d.transactions.length>100000)throw Error('Слишком большой файл.');for(const t of d.transactions){if(typeof t.id!=='string'||!validDate(t.date)||!['income','expense','transfer','adjustment','courier_payment','courier_return'].includes(t.type))throw Error('Ошибочная операция в резервной копии.');if(t.type==='adjustment'?!validCents(t.delta):!validCents(t.amount)||t.amount<=0)throw Error('Ошибочная сумма операции.');if(t.allocations&&(typeof t.allocations!=='object'||Object.values(t.allocations).some(v=>!validCents(v)||v<0)||Object.values(t.allocations).reduce((s,v)=>s+v,0)!==t.amount))throw Error('Неверное распределение дохода.');}
for(const c of d.categories)if(typeof c.id!=='string'||typeof c.name!=='string'||!['income','expense'].includes(c.type)||typeof c.icon!=='string')throw Error('Некорректная категория.');for(const b of d.budgets)if(!validCents(b.amount)||b.amount<=0||!['month','recurring'].includes(b.mode)||typeof b.categoryId!=='string')throw Error('Некорректный бюджет.');for(const s of d.subscriptions)if(!validCents(s.amount)||s.amount<=0||typeof s.name!=='string'||!validDate(s.nextDate)||!['weekly','monthly','yearly'].includes(s.frequency))throw Error('Некорректная подписка.');if(![0,7,30].includes(d.prefs.backupReminderDays))d.prefs.backupReminderDays=7;return d}
async function importBackup(file){if(!file)return;if(file.size>15*1024*1024){toast('Файл слишком большой.');return}try{const raw=JSON.parse(await file.text()),data=validateBackup(raw);const n=data.transactions.length;if(!confirm(`Восстановить ${n} операций из резервной копии?\n\nТЕКУЩИЕ ДАННЫЕ БУДУТ ПОЛНОСТЬЮ ЗАМЕНЕНЫ. Сначала рекомендуется скачать свою текущую копию.`))return;state=data;state.prefs.lastBackupAt=null;await commit();view='home';render();toast('Резервная копия восстановлена ✓')}catch(e){toast('Восстановление не выполнено: '+e.message);console.error(e)}}
async function clickAction(action,id){try{switch(action){case 'nav':view=id;render();window.scrollTo(0,0);break;case 'account':detailAccount=id;view='account';render();window.scrollTo(0,0);break;case 'open-new':newExpense();break;case 'open-expense':newExpense();break;case 'open-income':newIncome();break;case 'open-transfer':newTransfer(null,id);break;case 'open-adjustment':adjustment(id);break;case 'close-modal':closeModal();break;case 'edit-tx':{const t=state.transactions.find(x=>x.id===id);if(t)editTransaction(t);break}case 'edit-tx-full':{const t=state.transactions.find(x=>x.id===id);if(!t)return;closeModal();if(t.type==='expense')newExpense(t);else if(t.type==='income')newIncome(t);else if(t.type==='transfer')newTransfer(t);else editCourierSimple(t);break}case 'delete-tx':{const t=state.transactions.find(x=>x.id===id);if(t?.type==='courier_payment'&&outstanding()-t.amount<0){toast('Нельзя удалить оплату, пока возвраты превышают оставшуюся сумму долга.');return}if(t&&confirm('Удалить эту операцию? Балансы и бюджеты будут пересчитаны.')){state.transactions=state.transactions.filter(x=>x.id!==id);await commit();closeModal();render();toast('Операция удалена')}break}case 'month-prev':month=shiftMonth(month,-1);render();break;case 'month-next':month=shiftMonth(month,1);render();break;case 'history-type':historyType=id;render();break;case 'category-type':categoryType=id;render();break;case 'new-budget':newBudget();break;case 'edit-budget':newBudget(state.budgets.find(x=>x.id===id));break;case 'delete-budget':if(confirm('Удалить этот бюджет?')){state.budgets=state.budgets.filter(x=>x.id!==id);await commit();closeModal();render()}break;case 'new-category':newCategory();break;case 'edit-category':newCategory(cat(id));break;case 'delete-category':{const used=state.transactions.some(t=>t.categoryId===id)||state.budgets.some(b=>b.categoryId===id)||state.subscriptions.some(s=>s.categoryId===id);if(used){toast('Категория уже используется. Вместо удаления переведи её в архив.');return}if(confirm('Удалить неиспользуемую категорию?')){state.categories=state.categories.filter(x=>x.id!==id);await commit();closeModal();render();toast('Категория удалена')}break}case 'new-subscription':newSubscription();break;case 'edit-subscription':newSubscription(state.subscriptions.find(x=>x.id===id));break;case 'delete-subscription':if(confirm('Удалить подписку? Уже созданные расходы останутся.')){state.subscriptions=state.subscriptions.filter(x=>x.id!==id);await commit();closeModal();render()}break;case 'pay-subscription':{const s=state.subscriptions.find(x=>x.id===id);if(!s)return;if(!confirm(`Записать расход ${euro(s.amount)} со счёта «${acc(s.accountId)?.name}» и отметить подписку оплаченной?`))return;state.transactions.push({id:uid(),type:'expense',amount:s.amount,categoryId:s.categoryId,accountId:s.accountId,date:today(),note:'Подписка: '+s.name,createdAt:new Date().toISOString()});do{s.nextDate=shiftDue(s.nextDate,s.frequency)}while(s.nextDate<=today());await commit();render();toast('Оплата записана');break}case 'courier-pay':courierPayment();break;case 'courier-return':courierReturn();break;case 'backup-export':await exportBackup();break;case 'backup-import':$('#restore-file')?.click();break;case 'csv':exportCSV();break;}}
catch(e){toast(e.message||'Произошла ошибка');console.error(e)}}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn){e.preventDefault();clickAction(btn.dataset.action,btn.dataset.id||'')}else if(e.target?.id==='modal-backdrop')closeModal()});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-form]'))return;e.preventDefault();handleForm(e.target)});
document.addEventListener('input',e=>{if(e.target.id==='history-search'){historySearch=e.target.value;const input=e.target,sel=input.selectionStart;render();const next=$('#history-search');next?.focus();if(next)next.setSelectionRange(sel,sel)}});
document.addEventListener('change',async e=>{if(e.target.id==='backup-days'){state.prefs.backupReminderDays=Number(e.target.value);await commit();toast('Напоминания обновлены')}if(e.target.id==='restore-file'){await importBackup(e.target.files?.[0]);e.target.value=''}});
async function initialize(){try{db=await openDB();const saved=await dbRead();if(saved&&saved.schema===1)state=saved;else await commit();render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache unavailable',err));}catch(err){console.error(err);$('#app').innerHTML=`<main class="boot" style="padding:30px;text-align:center"><div class="boot-icon">⚠</div><h1>Не удалось открыть локальную базу</h1><p>${E(err.message)}</p><p>Проверь, что браузер разрешает хранение данных. Открой приложение через HTTPS или localhost, не в режиме инкогнито.</p></main>`}}
initialize();
